import time


class Timer:
    def __init__(self, label, clock=time.perf_counter):
        self.label = label
        self.clock = clock
        self.elapsed = None
        self.error = None
        self.records = []
        self._start = None

    def __enter__(self):
        self._start = self.clock()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.elapsed = round(self.clock() - self._start, 6)
        self.error = exc_type.__name__ if exc_type else None
        self.records.append({'label': self.label, 'elapsed': self.elapsed, 'ok': self.error is None})
        return False  # never suppress


# ---------------------------------------------------------------------------
# Test harness (do not change). `ticks` are the successive values the fake clock returns.
# ---------------------------------------------------------------------------
def run_timed(ticks, fail=False):
    clock = iter(ticks).__next__
    timer = Timer(label="report", clock=clock)
    propagated = None
    try:
        with timer as t:
            if t is not timer:
                return {"bug": "__enter__ must return self"}
            if fail:
                raise RuntimeError("boom")
    except RuntimeError as e:
        propagated = type(e).__name__
    return {"elapsed": timer.elapsed, "error": timer.error, "propagated": propagated,
            "records": timer.records}
